import java.util.Scanner;
public class JInput1 {
	public static void main(String[] args) {
		//Khatwa 1: Qra al-rakam al-awwal alladhi yadkhuluhu al-mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil rakm:");
		int num = scan.nextInt();
		//Khatwa 2: Atri al-rakam alladhi adkhalahu al-mustakhdim, thumma istaqbil al-a3dad al-talia ma damaa ann al-mustakhdim yadkhul ramzan ghayr salbi;  wa illa iftah
		while ( num >= 0 ) {
			System.out.println("Al-rakam al-mudkhal huwa " + num);
			System.out.println("Adkhil rakm:");
			num = scan.nextInt(); 
		}
		scan.close();
		System.out.println("Nihayat al-madkhul.");
	}
}
